{
	struct hv_dynmem_device *dm = dm_dev;

	while (!kthread_should_stop()) {
		wait_for_completion_interruptible_timeout(&dm_device.config_event,
								secs_to_jiffies(1));
		/*
		 * The host expects us to post information on the memory
		 * pressure every second.
		 */
